import{_ as o,l,o as e,c as s,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"数据库审计","description":"","frontmatter":{"title":"数据库审计","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/db-audit.md","filePath":"cs/db-audit.md","lastUpdated":1789023840000}'),A={name:"cs/db-audit.md"};function h(_,a,E,u,L,m){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="数据库审计" tabindex="-1">数据库审计 <a class="header-anchor" href="#数据库审计" aria-label="Permalink to &quot;数据库审计&quot;">​</a></h1><div class="epigraph"><p>授权决定能不能做；审计决定事后能否证明谁做了。没有不可抵赖的日志，RLS 与 GRANT 只是当前状态。</p><footer>—— 据数据库审计与合规实践；Gray 对事务日志作为真相来源的讨论对照</footer></div><p><a href="/cs/row-level-security">上一课</a>把行滤进计划。缺口是<strong>责任</strong>：谁在何时读了或改了哪一行。本课收束「数据库进阶」。下一课程分布式从 <a href="/cs/failure-models">故障模型</a> 起，审计日志不是共识，但共识课要假定有可查的历史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>WAL 服务崩溃恢复，不一定服务「谁 SELECT 了身份证」。审计：DDL/DML/登录、可选的列级读。缺口是性能与完整性：同步审计拖事务；异步会丢。日志必须防篡改（追加、校验、外送）。与 RLS：管理员绕过更要记。与 Jepsen：对抗测试不替代生产审计。</p><p><span class="marginnote">合规（谁访问了个人数据）与性能剖析不是同一份日志。混用会要么太重，要么太不可读。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义对象：登录、DDL、对敏感表的 DML、策略绕过。存储：独立卷或外部 SIEM，保留期。查询：按主体、对象、时间。测试：关掉审计应报警。与湖仓：表格式的提交日志是写审计，读审计仍要引擎配合。</p>',8)),(e(),d(c,null,{default:r(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E7%99%BB%E5%BD%95%20%2F%20DDL%20%2F%20DML%22%5D%20--%3E%20LOG%5B%22%E8%BF%BD%E5%8A%A0%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20LOG%20--%3E%20SIEM%5B%22%E5%A4%96%E9%80%81%20%2F%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20Q%5B%22%E8%B4%A3%E4%BB%BB%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20LOG%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>审计是另一条只追加的真实来源，与 WAL 并行。若与 WAL 同一磁盘、同一超级用户，崩溃恢复成功仍能毁证据。哈希链或外送使删改可被发现。同步审计进组提交路径会拖 D；异步会丢最后窗口——又一个持久性等级。体积：全 SELECT 审计在 OLAP 扫上等于再写一份元数据，要采样或只记对象。语句文本可能含敏感字面量，要脱敏。</p><p>保存点部分回滚仍可能已记下失败语句。存储过程记 CALL 还是展开内部 SQL，粒度要选。TPC 跑分通常关审计，报告须声明。读审计本身也要 RLS。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某司法辖区条文。数据库进阶在此封口：SQL、依赖、优化、执行、存储、事务、分布式、模型族、分析与流、对抗与授权。下一课程按大纲接分布式系统（故障模型等）。不要把审计当加密或当 WAL。</p><p>后课默认：事中 RLS、事后审计、底层 WAL/TDE。WAL 让你恢复数据；审计让你解释谁碰过数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>审计补上授权没有的时间轴与不可抵赖。</li><li>必须与 WAL 分失败域，并防篡改。</li><li>数据库进阶封口；下一课按大纲接分布式系统。</li><li>出处：数据库审计实践；Gray 对日志作为真相来源的讨论。</li></ul>',8))])}const T=o(A,[["render",h]]);export{D as __pageData,T as default};
